"""Expected results for the Java Python-expression evaluator (java/.../py/PyEval), generated by CPython itself.

Every case is one expression, evaluated the way the compiler evaluates `$"..."` expressions:
eval(expr, {'math': math, 'json': json}, locals) with a fresh copy of LOCALS. The expected value is the repr() of
the result, or the exception's type and str(), plus whatever print() wrote.

Output: java/src/test/resources/pyeval_cases.tsv, one case per line:
	expr <TAB> R:repr | E:Type: message <TAB> printed
with backslash, tab, newline and carriage return escaped as \\ \t \n \r.

Run with python3 (3.13 on Linux/glibc, the reference the goldens are made with). The script re-executes itself with
PYTHONHASHSEED=0 so str hashes and set orders are reproducible. Random cases are seeded: the file only changes when
this script does.
"""
import builtins
import copy
import io
import json
import math
import os
import random
import re
import struct
import sys

if os.environ.get('PYTHONHASHSEED') != '0':
	os.environ['PYTHONHASHSEED'] = '0'
	os.execv(sys.executable, [sys.executable] + sys.argv)

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(os.path.dirname(HERE), 'java', 'src', 'test', 'resources', 'pyeval_cases.tsv')

# The dollar ids a compile-time expression typically sees.
LOCALS = {
	'i': 7, 'f': 2.5, 's': 'text', 'l': [1, 2, 3], 't': (4, 5), 'd': {'a': 1, 'b': [2, 3]}, 'e': [],
	'neg': -3, 'big': 2 ** 70, 'name': 'Moddy', 'x': 0.1, 'n': 0, 'u': 'é☃😀', 'nested': [[1, 2], [3, [4, 5]]],
}

# Names the Java evaluator refuses although Python's eval would find them: Java must raise NameError.
REFUSED = ['__import__', 'open', 'exec', 'eval', 'compile', 'globals', 'locals', 'vars', 'getattr', 'setattr',
	'delattr', 'input', 'breakpoint', 'exit', 'quit', 'help', '__builtins__']

CASES = []


def add(*exprs):
	CASES.extend(exprs)


