# ---------------------------------------------------------------------------------------------------------------------
# Generated cases (seeded)
# ---------------------------------------------------------------------------------------------------------------------

rnd = random.Random(20261125)


def rand_double(r):
	"""A random finite double across the whole exponent range."""
	while True:
		b = r.getrandbits(64)
		x = struct.unpack('<d', struct.pack('<Q', b))[0]
		if math.isfinite(x):
			return x


def wide(r, lo, hi):
	return r.choice([1, -1]) * 10 ** r.uniform(lo, hi)


def lit(x):
	return repr(x) if x >= 0 else '(%r)' % x


# float repr of arbitrary doubles: the literal round-trips, and arithmetic on it exercises shortest-repr.
for _ in range(250):
	x = rand_double(rnd)
	add(lit(x))
for _ in range(150):
	a = wide(rnd, -30, 30)
	b = wide(rnd, -30, 30)
	add('%s %s %s' % (lit(a), rnd.choice(['+', '-', '*', '/', '%', '//']), lit(b)))
for _ in range(60):
	add('%d / %d' % (rnd.randint(-10 ** 6, 10 ** 6), rnd.randint(1, 10 ** 4)))
	add('%d / %d' % (rnd.getrandbits(200) - 2 ** 199, rnd.getrandbits(120) + 1))
for _ in range(80):
	add('round(%r, %d)' % (round(rnd.uniform(-1000, 1000), rnd.randint(1, 6)) + rnd.choice([0, 5e-7, -5e-7, 0.0005]),
		rnd.randint(-2, 5)))
for _ in range(60):
	x = wide(rnd, -8, 12)
	spec = rnd.choice(['.2f', '.3e', 'g', '.10g', ',.1f', '>12.4f', '+.0f', '%', '.1%', 'e', '.15g', '.17g', ''])
	add("format(%s, '%s')" % (lit(x), spec))
	add("'%%.%df' %% %s" % (rnd.randint(0, 8), lit(x)))

# big ints
for _ in range(40):
	a = rnd.getrandbits(rnd.randint(60, 300)) * rnd.choice([1, -1])
	b = rnd.getrandbits(rnd.randint(1, 200)) * rnd.choice([1, -1]) or 3
	add('%d %s %d' % (a, rnd.choice(['+', '-', '*', '//', '%', '&', '|', '^']), b))
	add('divmod(%d, %d)' % (a, b))

# str repr of characters across the code point range (escaping rules)
cps = list(range(0, 0x100)) + [0x2028, 0x2029, 0x200b, 0x200e, 0xfeff, 0x061c, 0x0378, 0x1680, 0x3000, 0xe000,
	0xfffd, 0xffff, 0x10000, 0x1f600, 0xe0001, 0xf0000, 0x10fffd, 0x10ffff, 0xd7ff, 0xdc00]
for c in cps:
	add('repr(chr(%d))' % c)
for _ in range(60):
	c = rnd.choice([rnd.randint(0x100, 0xd7ff), rnd.randint(0xe000, 0xffff), rnd.randint(0x10000, 0x10ffff)])
	add('repr(chr(%d) + "a")' % c)

# sets of ints and strings (iteration order follows CPython's hash table)
for _ in range(40):
	k = rnd.randint(0, 30)
	add('{%s}' % ', '.join(str(rnd.randint(-50, 300)) for _ in range(k)) if k else 'set()')
for _ in range(15):
	words = ['%s%d' % (rnd.choice(['a', 'b', 'mc', 'x_', 'Z']), rnd.randint(0, 999)) for _ in range(rnd.randint(1, 12))]
	add('{%s}' % ', '.join(repr(w) for w in words))
	add('hash(%r)' % words[0])
for _ in range(10):
	a = sorted(rnd.sample(range(100), 12))
	b = sorted(rnd.sample(range(100), 9))
	for op in ['|', '&', '-', '^']:
		add('set(%r) %s set(%r)' % (a, op, b))

# transcendental functions: bit-exactness with glibc
for _ in range(60):
	for fn in ['sin', 'cos', 'tan']:
		add('math.%s(%s)' % (fn, lit(rnd.choice([rnd.uniform(-10, 10), wide(rnd, -8, 22), rnd.uniform(-1e6, 1e6)]))))
for _ in range(80):
	add('math.exp(%s)' % lit(rnd.choice([rnd.uniform(-745, 709), rnd.uniform(-1, 1), wide(rnd, -12, 2)])))
	add('math.log(%s)' % lit(abs(rnd.choice([wide(rnd, -300, 300), rnd.uniform(0.9, 1.1)]))))
	add('math.atan2(%s, %s)' % (lit(wide(rnd, -20, 20)), lit(wide(rnd, -20, 20))))
	add('math.pow(%s, %s)' % (lit(abs(wide(rnd, -10, 10))), lit(rnd.uniform(-30, 30))))
	add('%s ** %s' % (lit(abs(wide(rnd, -5, 5))), lit(rnd.uniform(-20, 20))))
for _ in range(30):
	add('math.log10(%s)' % lit(abs(wide(rnd, -100, 100))))
	add('math.log2(%s)' % lit(abs(wide(rnd, -100, 100))))
	add('math.log(%s, %s)' % (lit(abs(wide(rnd, -10, 10))), lit(abs(wide(rnd, -3, 3)))))
	add('math.asin(%s)' % lit(rnd.uniform(-1, 1)))
	add('math.acos(%s)' % lit(rnd.uniform(-1, 1)))
	add('math.atan(%s)' % lit(wide(rnd, -10, 10)))
	add('math.sinh(%s)' % lit(rnd.uniform(-30, 30)))
	add('math.cosh(%s)' % lit(rnd.uniform(-30, 30)))
	add('math.tanh(%s)' % lit(rnd.uniform(-5, 5)))
	add('math.hypot(%s, %s)' % (lit(wide(rnd, -10, 10)), lit(wide(rnd, -10, 10))))
	add('math.expm1(%s)' % lit(rnd.uniform(-2, 2)))
	add('math.sqrt(%s)' % lit(abs(wide(rnd, -300, 300))))
	add('math.degrees(%s)' % lit(rnd.uniform(-7, 7)))
	add('math.radians(%s)' % lit(rnd.uniform(-720, 720)))

# ---------------------------------------------------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------------------------------------------------

def escape(s):
	return s.replace('\\', '\\\\').replace('\t', '\\t').replace('\n', '\\n').replace('\r', '\\r')


def refused_attribute(expr):
	"""The Java evaluator refuses attributes starting with '_': the AttributeError CPython gives for a missing one."""
	m = re.match(r'^(.*)\.(_\w*)$', expr)
	if not m:
		return None
	obj = eval(m.group(1), {'math': math, 'json': json}, copy.deepcopy(LOCALS))
	if isinstance(obj, type(math)):
		return 'E:AttributeError: module %r has no attribute %r' % (obj.__name__, m.group(2))
	if isinstance(obj, type):
		return 'E:AttributeError: type object %r has no attribute %r' % (obj.__name__, m.group(2))
	return 'E:AttributeError: %r object has no attribute %r' % (type(obj).__name__, m.group(2))


def evaluate(expr):
	if expr in REFUSED or expr.split('(')[0] in REFUSED:
		name = expr.split('(')[0]
		return 'E:NameError: name %r is not defined' % name, ''
	refused = refused_attribute(expr)
	if refused:
		return refused, ''
	out = io.StringIO()
	saved = sys.stdout
	sys.stdout = out
	try:
		import warnings
		with warnings.catch_warnings():
			warnings.simplefilter('ignore')
			value = eval(expr, {'math': math, 'json': json}, copy.deepcopy(LOCALS))
		if isinstance(value, complex):
			return None, None  # complex numbers are refused by the Java evaluator
		result = 'R:' + repr(value)
	except BaseException as e:
		result = 'E:%s: %s' % (type(e).__name__, e)
	finally:
		sys.stdout = saved
	if ' at 0x' in result or ' at 0x' in out.getvalue():
		return None, None  # object addresses are not reproducible
	return result, out.getvalue()


def main():
	seen = set()
	lines = []
	skipped = 0
	for expr in CASES:
		if expr in seen:
			continue
		seen.add(expr)
		result, printed = evaluate(expr)
		if result is None:
			skipped += 1
			continue
		lines.append('%s\t%s\t%s' % (escape(expr), escape(result), escape(printed)))
	with open(OUT, 'w', encoding='utf-8', newline='\n') as f:
		f.write('\n'.join(lines) + '\n')
	print('%d cases written to %s (%d skipped)' % (len(lines), os.path.relpath(OUT), skipped))


if __name__ == '__main__':
	main()
